// === Tab: mySketch ===
/**
 * GENERADOR DE FIBRAS B/N - ESTILO TOUCHDESIGNER
 * Características: Flow Fields, Interacción de Mouse (Remolino/Explosión), UI Activa, 4+ Teclas.
 * PURO JAVASCRIPT PARA OPENPROCESSING
 */

let fibras = [];
let zOff = 0;

// Variables de Estado (Teclas)
let invertido = false;  // Tecla [I]
let caotico = false;    // Tecla [C]
let pausado = false;    // Tecla [P]

// UI DOM Elements
let sliderCantidad, sliderRuido, sliderVelocidad, sliderRastro;
let btnInvertir, btnReset;

// Panel UI visual
let uiX = 20;
let uiY = 20;

function setup() {
  createCanvas(windowWidth, windowHeight);
  background(0);

  // Inicializamos la interfaz de usuario (Botones y Sliders)
  crearUI();

  // Generamos las fibras iniciales
  ajustarCantidadFibras(sliderCantidad.value());
}

function draw() {
  if (pausado) {
    dibujarPanelUI(); // Mantener la UI visible aunque esté en pausa
    return;
  }

  // 1. FASE DE RASTRO (Feedback Fade / Level TOP sim)
  // En lugar de borrar la pantalla, dibujamos un rectángulo casi transparente
  noStroke();
  let rastro = sliderRastro.value();
  if (invertido) {
    fill(255, rastro); // Si está invertido, el fondo vuelve a blanco lentamente
  } else {
    fill(0, rastro);   // Fondo vuelve a negro lentamente
  }
  rect(0, 0, width, height);

  // 2. ACTUALIZAR Y DIBUJAR FIBRAS
  ajustarCantidadFibras(sliderCantidad.value());

  // Configuración de dibujo para las fibras
  if (invertido) {
    stroke(0, 30); // Fibras negras sobre fondo blanco
  } else {
    stroke(255, 30); // Fibras blancas sobre fondo negro
  }
  strokeWeight(1);
  noFill();

  for (let f of fibras) {
    f.actualizar();
    f.dibujar();
  }

  // Evolución del campo de ruido
  zOff += caotico ? 0.02 : 0.003; 

  // 3. DIBUJAR PANEL UI ENCIMA DEL LIENZO
  dibujarPanelUI();
}

// ------------------------------------------
// CLASE FIBRA (Agente)
// ------------------------------------------
class Fibra {
  constructor() {
    this.pos = createVector(random(width), random(height));
    this.posAnterior = this.pos.copy();
    this.vel = createVector(0, 0);
    this.acc = createVector(0, 0);
  }

  actualizar() {
    this.posAnterior.set(this.pos); // Guardar posición para la línea continua

    // --- Lógica del Ruido (Flow Field) ---
    let escala = sliderRuido.value();
    let angulo = noise(this.pos.x * escala, this.pos.y * escala, zOff) * TWO_PI * 4;

    // Si está en modo caótico, distorsionamos el ángulo
    if (caotico) angulo += noise(this.pos.x * 0.1, this.pos.y * 0.1) * PI;

    let fuerzaRuido = p5.Vector.fromAngle(angulo);
    fuerzaRuido.mult(0.5);
    this.acc.add(fuerzaRuido);

    // --- Interacción con el Mouse ---
    let raton = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
    let vectorRaton = p5.Vector.sub(this.pos, raton);
    let distancia = vectorRaton.mag();

    if (distancia < 200) {
      vectorRaton.normalize();

      if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && mouseButton === LEFT) {
        // [CLIC IZQUIERDO]: Explosión Repulsiva Fuerte
        let fuerzaExplosion = map(distancia, 0, 200, 15, 0);
        vectorRaton.mult(fuerzaExplosion);
        this.acc.add(vectorRaton);
      } else {
        // [MOVER MOUSE]: Remolino suave (Swirl)
        // Rotamos el vector 90 grados para crear un flujo circular alrededor del cursor
        vectorRaton.rotate(HALF_PI); 
        let fuerzaRemolino = map(distancia, 0, 200, 2, 0);
        vectorRaton.mult(fuerzaRemolino);
        this.acc.add(vectorRaton);
      }
    }

    // --- Físicas ---
    this.vel.add(this.acc);
    this.vel.limit(sliderVelocidad.value()); // Limitar según el slider
    this.pos.add(this.vel);
    this.acc.mult(0); // Resetear aceleración

    // --- Envolver bordes de la pantalla ---
    this.envolverBordes();
  }

  dibujar() {
    // Dibujar línea desde la posición anterior a la actual
    line(this.posAnterior.x, this.posAnterior.y, this.pos.x, this.pos.y);
  }

  envolverBordes() {
    let salio = false;
    if (this.pos.x > width)  { this.pos.x = 0; salio = true; }
    if (this.pos.x < 0)      { this.pos.x = width; salio = true; }
    if (this.pos.y > height) { this.pos.y = 0; salio = true; }
    if (this.pos.y < 0)      { this.pos.y = height; salio = true; }

    // Si cruza el borde, evitar que dibuje una línea cruzando toda la pantalla
    if (salio) {
      this.posAnterior.set(this.pos);
    }
  }
}

// ------------------------------------------
// INTERACCIÓN: TECLADO
// ------------------------------------------
function keyPressed() {
  let tecla = key.toLowerCase();

  if (tecla === 'i') {
    // 1. Tecla [I]: Invertir Colores
    invertido = !invertido;
    background(invertido ? 255 : 0); // Limpiar pantalla al invertir
  } 
  else if (tecla === 'c') {
    // 2. Tecla [C]: Modo Caos
    caotico = !caotico;
  } 
  else if (tecla === 'p') {
    // 3. Tecla [P]: Pausa
    pausado = !pausado;
  } 
  else if (tecla === 'r') {
    // 4. Tecla [R]: Resetear todo
    background(invertido ? 255 : 0);
    zOff = random(100);
    fibras = []; // Vacía y se rellenará en el próximo frame
  }
}

// ------------------------------------------
// UI Y HERRAMIENTAS ADICIONALES
// ------------------------------------------
function crearUI() {
  let uiOffset = uiY + 50;

  // Slider: Cantidad
  sliderCantidad = createSlider(100, 3000, 1200, 100);
  sliderCantidad.position(uiX + 15, uiOffset);
  uiOffset += 40;

  // Slider: Escala de Ruido
  sliderRuido = createSlider(0.001, 0.02, 0.006, 0.001);
  sliderRuido.position(uiX + 15, uiOffset);
  uiOffset += 40;

  // Slider: Velocidad
  sliderVelocidad = createSlider(1, 15, 5, 0.5);
  sliderVelocidad.position(uiX + 15, uiOffset);
  uiOffset += 40;

  // Slider: Rastro (Fade)
  sliderRastro = createSlider(1, 100, 10, 1); // Mientras más bajo, más largo el rastro
  sliderRastro.position(uiX + 15, uiOffset);
  uiOffset += 40;

  // Botón: Invertir
  btnInvertir = createButton('Invertir B/N');
  btnInvertir.position(uiX + 15, uiOffset);
  btnInvertir.mousePressed(() => {
    invertido = !invertido;
    background(invertido ? 255 : 0);
  });

  // Botón: Reiniciar
  btnReset = createButton('Reset Fibras');
  btnReset.position(uiX + 115, uiOffset);
  btnReset.mousePressed(() => {
    background(invertido ? 255 : 0);
    fibras = [];
  });
}

function dibujarPanelUI() {
  // Fondo de la caja UI
  noStroke();
  fill(invertido ? 255 : 0, 200); // Semitransparente para ver a través
  rect(uiX, uiY, 220, 360, 8);

  // Borde
  stroke(invertido ? 0 : 255, 50);
  strokeWeight(1);
  noFill();
  rect(uiX, uiY, 220, 360, 8);

  // Textos y Etiquetas
  noStroke();
  fill(invertido ? 0 : 255);
  textAlign(LEFT, TOP);

  textSize(16);
  text("CONTROL DE FIBRAS", uiX + 15, uiY + 15);
  stroke(invertido ? 0 : 255, 100);
  line(uiX + 15, uiY + 35, uiX + 205, uiY + 35);

  noStroke();
  textSize(12);
  let textoY = uiY + 40;

  text(`Fibras: ${sliderCantidad.value()}`, uiX + 15, textoY);
  textoY += 40;
  text(`Ruido (Escala): ${sliderRuido.value()}`, uiX + 15, textoY);
  textoY += 40;
  text(`Velocidad Max: ${sliderVelocidad.value()}`, uiX + 15, textoY);
  textoY += 40;
  text(`Fade / Rastro: ${sliderRastro.value()}`, uiX + 15, textoY);

  textoY += 75;
  // Panel de Información de Interacción
  fill(invertido ? 50 : 200);
  text("INTERACCIONES:", uiX + 15, textoY);
  textoY += 20;

  fill(invertido ? 0 : 255);
  let statusCaos = caotico ? "[ON]" : "[OFF]";
  let statusPausa = pausado ? "[ON]" : "[OFF]";

  text(`[ I ] Invertir B/N`, uiX + 15, textoY); textoY += 15;
  text(`[ C ] Modo Caótico ${statusCaos}`, uiX + 15, textoY); textoY += 15;
  text(`[ P ] Pausar ${statusPausa}`, uiX + 15, textoY); textoY += 15;
  text(`[ R ] Reiniciar Lienzo`, uiX + 15, textoY); textoY += 20;

  text(`MOUSE:  Remolino`, uiX + 15, textoY); textoY += 15;
  text(`CLIC:   Explosión`, uiX + 15, textoY);
}

// Función auxiliar para mantener la cantidad de objetos igual al slider
function ajustarCantidadFibras(objetivo) {
  if (fibras.length < objetivo) {
    let faltantes = objetivo - fibras.length;
    for (let i = 0; i < faltantes; i++) {
      fibras.push(new Fibra());
    }
  } else if (fibras.length > objetivo) {
    // Si bajamos el slider, eliminamos fibras
    fibras.splice(objetivo);
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  background(invertido ? 255 : 0);
}

